package com.foodprocurement.repository;
import com.foodprocurement.domain.Entities.*; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository;
public final class Repositories { private Repositories(){} public interface Standards extends JpaRepository<FoodStandard,UUID>{} public interface Suppliers extends JpaRepository<Supplier,UUID>{} public interface Plans extends JpaRepository<ProcurementPlan,UUID>{} public interface Inquiries extends JpaRepository<Inquiry,UUID>{} public interface Bids extends JpaRepository<Bid,UUID>{ List<Bid> findByInquiryIdOrderByAmountAsc(UUID inquiryId); } public interface Orders extends JpaRepository<PurchaseOrder,UUID>{} public interface Deliveries extends JpaRepository<Delivery,UUID>{} public interface Inspections extends JpaRepository<Inspection,UUID>{} public interface Lots extends JpaRepository<InventoryLot,UUID>{ List<InventoryLot> findByLotNo(String lotNo); } public interface Settlements extends JpaRepository<Settlement,UUID>{} }
